/**
 * URL slug generation for admin-created content.
 *
 * The previous inline helper kept only `[a-z0-9]`, so a product whose title is
 * Russian ("Современные бархатные шторы") or Uzbek with diacritics
 * ("Zamonaviy baxmal — yangi") collapsed to an empty or truncated slug. An
 * empty slug means an unreachable public page and a unique-constraint crash on
 * the second such item, so slugs are generated by transliteration instead.
 */

const TRANSLITERATION: Record<string, string> = {
  // Cyrillic (ru)
  а: "a", б: "b", в: "v", г: "g", д: "d", е: "e", ё: "yo", ж: "zh",
  з: "z", и: "i", й: "y", к: "k", л: "l", м: "m", н: "n", о: "o",
  п: "p", р: "r", с: "s", т: "t", у: "u", ф: "f", х: "kh", ц: "ts",
  ч: "ch", ш: "sh", щ: "shch", ъ: "", ы: "y", ь: "", э: "e", ю: "yu",
  я: "ya",
  // Uzbek Latin diacritics and apostrophe forms
  "ʻ": "", "ʼ": "", "‘": "", "’": "", "'": "", "`": "",
  ғ: "g", қ: "q", ҳ: "h", ў: "o", ҷ: "j",
  // Latin accents seen in imported copy
  á: "a", à: "a", ä: "a", â: "a", é: "e", è: "e", ë: "e", ê: "e",
  í: "i", ì: "i", ï: "i", î: "i", ó: "o", ò: "o", ö: "o", ô: "o",
  ú: "u", ù: "u", ü: "u", û: "u", ç: "c", ñ: "n", ý: "y",
};

export function slugify(input: string, maxLength = 200): string {
  const transliterated = Array.from(input.toLowerCase())
    .map((char) => TRANSLITERATION[char] ?? char)
    .join("");

  return transliterated
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, maxLength)
    .replace(/-+$/g, "");
}

/**
 * A slug that can always be stored. If the title has no Latin-representable
 * characters at all (e.g. an emoji-only draft), fall back to a stable prefix so
 * the row is still reachable instead of colliding with every other empty slug.
 */
export function slugifyOrFallback(input: string, prefix: string, fallbackId?: number | string): string {
  const slug = slugify(input);
  if (slug.length >= 2) return slug;
  if (fallbackId !== undefined) return `${prefix}-${fallbackId}`;
  return `${prefix}-${Date.now().toString(36)}`;
}

/**
 * Postgres unique-violation detection that works whether the driver reports a
 * `code` on the error itself or on a wrapped cause.
 */
export function isUniqueViolation(error: unknown): boolean {
  let current: unknown = error;
  for (let depth = 0; depth < 4 && current; depth += 1) {
    if (typeof current === "object" && current !== null) {
      const code = (current as { code?: unknown }).code;
      if (code === "23505") return true;
      current = (current as { cause?: unknown }).cause;
    } else {
      break;
    }
  }
  return false;
}
